def classify_status(code):
    category = code // 100
    if category == 2:
        return 'ok'
    if category == 4:
        return 'client_error'
    if category == 5:
        return 'server_error'
    return 'other'

def is_safe_update(query):
    q = query.strip().upper()
    return q.startswith('UPDATE ') and ' WHERE ' in q

def summarize_git_changes(lines):
    out = {'added': 0, 'modified': 0, 'deleted': 0}
    mapping = {'A': 'added', 'M': 'modified', 'D': 'deleted'}
    for line in lines:
        parts = line.split(maxsplit=1)
        if not parts:
            continue
        key = mapping.get(parts[0])
        if key:
            out[key] += 1
    return out

def filter_logs(lines, keyword):
    k = keyword.lower()
    return [line for line in lines if k in line.lower()]

