class LogAnalyzer:
    def __init__(self, logs):
        self._logs = logs

    def filter_errors(self):
        return [l for l in self._logs if l.get('status', 0) >= 400]

    def group_by_status(self):
        groups = {}
        for log in self._logs:
            status = log.get('status', 0)
            groups.setdefault(str(status), []).append(log)
        return groups

    def method_counts(self):
        counts = {}
        for log in self._logs:
            method = log.get('method', 'UNKNOWN')
            counts[method] = counts.get(method, 0) + 1
        return counts

    def error_rate(self):
        if not self._logs:
            return 0.0
        return round(len(self.filter_errors()) / len(self._logs), 2)

    def summary(self):
        return {
            'total': len(self._logs),
            'errors': len(self.filter_errors()),
            'error_rate': self.error_rate(),
            'methods': self.method_counts(),
        }
